<script setup lang="ts">import{onBeforeUnmount,ref}from"vue";import{iptvSourceRepository}from"@/domain/repositories";import{testStreamInBrowser}from"@/domain/iptv/browserTest";import type{IptvSourceRecord}from"@/types/records";const props=defineProps<{link:IptvSourceRecord}>();const emit=defineEmits<{tested:[IptvSourceRecord]}>();const running=ref(false),message=ref("");let controller:AbortController|null=null;async function run(){controller=new AbortController();running.value=true;message.value="";try{const result=await testStreamInBrowser(props.link,15000,controller.signal);message.value=result.message;const updated=await iptvSourceRepository.update(props.link.id,{ultimo_teste_em:result.testedAt,ultimo_estado:result.state,metadata_extra:{...(typeof props.link.metadata_extra==="object"&&props.link.metadata_extra?props.link.metadata_extra:{}),ultimo_teste_browser:{elapsed_ms:result.elapsedMs,content_type:result.contentType,http_status:result.httpStatus,message:result.message}}});emit("tested",updated as IptvSourceRecord)}catch(c){message.value=c instanceof Error?c.message:String(c)}finally{running.value=false;controller=null}}function cancel(){controller?.abort()}onBeforeUnmount(cancel)</script><template><div class="stream-test-action"><button class="button button-secondary" type="button" :disabled="running" @click="run">{{running?"A testar…":"Testar"}}</button><button v-if="running" class="button button-secondary" type="button" @click="cancel">Cancelar</button><small v-if="message" aria-live="polite">{{message}}</small></div></template>
